style.css:
@-moz-document domain("mail.google.com") {
/* 1. FORCE DARK BACKGROUND ON EVERYTHING */
  html, body, .wl, .ji, .yO, .Nr, .aKh, .ws, .a7O {
    background-color: #232a2d !important;
    color: #e8eaed !important;
  }

  /* 2. OVERRIDE SIMPLIFY'S WHITE ROWS */
  /* This targets every single email row, regardless of read/unread state */
  .zA, .zA > .yO, .zA > .zE, .KV, .h0, .cZ {
    background-color: #232a2d !important;
    border-bottom: 1px solid #3c4043 !important; /* Adds separator */
  }

  /* 3. MINT HIGHLIGHTS */
  /* Sidebar icons, text, and active folders */
  .n6, .TN, .nZ, .qj, .aHS-bnt .ain, .TO .nU > .n0, .J-Ke, .CL, .Wl {
    color: #8ccf7e !important;
  }
  
  /* 4. THE "INBOX" PILL (Simplify Gmail Specific) */
  /* This attempts to color the blue pill in the top left */
  .T-I-KE, .nZ, .b3, .Z0, .L3 {
    background-color: #8ccf7e !important;
    color: #232a2d !important;
  }

  /* 5. FIX TEXT COLOR IN ROWS */
  /* Ensures text is readable on dark background */
  .y6, .zF, .bQ, .yW, .xY, .y2, .bA, .a4W {
    color: #e8eaed !important;
  }

  /* 6. HEADER & SEARCH BAR */
  header, .gb_He, .gb_re, .gb_Id, .gb_od, .G-atb {
    background-color: #232a2d !important;
  }
  
  /* 7. SCROLLBARS */
  ::-webkit-scrollbar { width: 12px; }
  ::-webkit-scrollbar-track { background: #232a2d; }
  ::-webkit-scrollbar-thumb { background-color: #5f6368; border: 3px solid #232a2d; border-radius: 10px; }
}
